using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Expenses.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.Expenses.Commands.CreateExpense;public sealed class CreateExpenseCommandHandler(IExpenseRepository repository,IApplicationDbContext db):IRequestHandler<CreateExpenseCommand,Result<ExpenseDto>>{public async Task<Result<ExpenseDto>>Handle(CreateExpenseCommand request,CancellationToken cancellationToken){if(await repository.ExistsByExpenseNumberAsync(request.ExpenseNumber,cancellationToken))return Result.Failure<ExpenseDto>(ExpenseErrors.Duplicate);var e=Expense.Create(request.ExpenseNumber,request.ExpenseDate,request.Category,request.Description,request.Amount,request.CreatedByUserId,request.ProjectId);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(ExpenseDto.FromEntity(e));}}
